int main(){int n,m; cin>>n>>m;
 vector<string> g(n*m); for(auto&x:g) cin>>x;
 vector<string> out; int top=0,bottom=n-1,left=0,right=m-1;
 while(top<=bottom&&left<=right){
 for(int j=left;j<=right;j++) out.push_back(g[top*m+j]);
 top++;
 for(int i=top;i<=bottom;i++) out.push_back(g[i*m+right]);
 right--;
 if(top<=bottom){ for(int j=right;j>=left;j--) out.push_back(g[bottom*m+j]); bottom--; }
 if(left<=right){ for(int i=bottom;i>=top;i--) out.push_back(g[i*m+left]); left++; }
 }
 for(size_t i=0;i<out.size();i++) cout<<out[i]<<" \n"[i+1==out.size()];
